insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000001','id','anak','Yuk, Kenalan dengan Hewan Purba Indonesia!','Jutaan tahun lalu, Indonesia dihuni banyak hewan purba yang unik! Ada Megalochelys sp., si kura-kura raksasa. Ada juga Elephas celebensis, gajah purba mungil dari Sulawesi. Bersama Elephas maximus dan Sinomastodon bumiayuensis, fosil-fosil ini menjadi saksi beragamnya hewan di masa lalu. Ayo amati dan temukan perbedaannya!','Tahukah kamu? Elephas celebensis adalah salah satu gajah purba berukuran kecil yang pernah hidup di Sulawesi.','Megalochelys sp., Elephas celebensis, Elephas maximus, Sinomastodon bumiayuensis') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000002','id','anak','Rahasia Gua dan Karst','Pernah melihat gua dengan hiasan batu yang menjuntai dari langit-langitnya? Itu salah satu keunikan kawasan karst, seperti Gunung Sewu! Karst terbentuk saat batuan kapur larut perlahan selama waktu yang sangat lama. Ayo amati stalaktit, sinter kapur, batu jahe, berbagai jenis batuan, dan terumbu karang!','Tahukah kamu? Stalaktit terbentuk dari endapan mineral kalsit yang menumpuk sedikit demi sedikit dari tetesan air di langit-langit gua.','Karst Gunung Sewu, stalaktit kalsit, batugamping, batu jahe, sinter kapur, marmer, amfibolit, hasil karstifikasi, hard coral, plate coral, branching coral, head coral') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000003','id','anak','Indonesia di Cincin Api','Tahukah kamu? Indonesia berada di jalur pertemuan lempeng yang disebut Cincin Api Pasifik. Pertemuan lempeng ini membentuk deretan gunung api dari Sumatra sampai Maluku. Ayo lihat peta di depanmu, lalu temukan gunung api yang paling dekat dengan Bandung!','Deretan gunung api dari Sumatra sampai Maluku terbentuk karena pertemuan lempeng di jalur Cincin Api Pasifik.','Peta sebaran gunung api') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000004','id','anak','Bumi yang Terus Berubah','Tahukah kamu? Bentuk muka bumi Indonesia terbentuk lewat proses geologi selama jutaan tahun! Pergerakan dan tekanan lempeng bumi menghasilkan struktur batuan, seperti lipatan dan sesar. Yuk, amati genes, sekis biotit, dan contoh struktur geologi untuk melihat bagaimana bumi terus berubah!','Lipatan terbentuk saat lapisan batuan ditekan sampai melengkung, tanpa terpecah.','Genes, sekis biotit, lipatan, sesar') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000005','id','anak','Lahirnya Kepulauan Indonesia','Pernah penasaran bagaimana ribuan pulau di Indonesia terbentuk? Lewat animasi ini, kamu bisa mengikuti perjalanannya! Pulau-pulau itu terbentuk karena pergerakan lempeng tektonik, aktivitas gunung api, dan proses geologi selama jutaan tahun. Yuk, saksikan bagaimana daratan yang awalnya terpisah akhirnya membentuk Indonesia seperti sekarang!','Bentuk kepulauan Indonesia masih terus berubah sampai sekarang karena aktivitas tektonik.','video') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000006','id','anak','Tiga Pembentuk Wajah Bumi','Bentuk permukaan bumi yang kita lihat sekarang terbentuk lewat proses alam selama ribuan hingga jutaan tahun. Ada tiga proses yang bekerja. Pelapukan menghancurkan batuan, erosi memindahkan material, dan pengendapan menumpuknya di tempat baru. Yuk, amati contoh bentukan muka bumi dan lihat bagaimana ketiganya mengubah lanskap Indonesia!','Material hasil erosi bisa terbawa air, angin, atau es sebelum akhirnya mengendap di tempat lain.','Bentukan morfologi muka bumi, pelapukan, erosi, dan pengendapan') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000007','id','anak','Harta Karun Bumi: Batuan dan Mineral','Bumi menyimpan banyak mineral dan batuan dengan warna dan bentuk yang berbeda-beda! Ada lapis lazuli yang terkenal dengan warna biru pekatnya. Ada juga geodes yang menyimpan kristal di bagian dalamnya. Yuk, amati koleksi mineralnya dan kenali tiga kelompok utama batuan: beku, sedimen, dan metamorf!','Geodes bisa terlihat seperti batu biasa dari luar, tetapi bagian dalamnya bisa dipenuhi kristal yang indah.','Lapis lazuli, mineral hidroksida, oksida, silikat, karbonat, borat dan nitrat, unsur asli (native elements), sulfida, fosfat, sulfat, batuan beku, batuan sedimen, batuan metamorf, geodes') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000008','id','anak','Bumi yang Tidak Pernah Diam','Tahukah kamu? Permukaan bumi yang kita pijak ternyata terus bergerak! Tenaga tektonik berasal dari pergerakan lempeng bumi, yang bisa membentuk pegunungan, lipatan, dan patahan. Yuk, amati sekis mika, peridotit, dan lava basal untuk mengenal proses yang membentuk bumi!','Peridotit adalah batuan yang banyak menyusun bagian mantel atas bumi.','Proses terjadinya tenaga tektonik, sekis mika, peridotit, lava basal') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
