select '40000000-0000-4000-8000-000000000006','id','dewasa','Trio Pembentuk Lanskap','Tiga proses bekerja mengubah wajah bumi: satu, pelapukan. Dua, erosi. Tiga, pengendapan. Peran mereka: A, memindahkan material lewat air, angin, atau es. B, menumpuk material di tempat baru. C, menghancurkan batuan. Pilih pasangan yang tepat!','Urutan kerjanya: batuan hancur dulu, lalu berpindah, lalu menetap.',NULL,NULL,ARRAY[]::text[],'Pelapukan menghancurkan batuan, erosi memindahkan material hasil pelapukan lewat air, angin, atau es, dan pengendapan menumpuknya di tempat baru.',NULL
