select '40000000-0000-4000-8000-000000000002','id','dewasa','Tetesan dari Langit-Langit Gua','Di gua karst, tetesan air kaya kalsit perlahan membentuk hiasan batu yang menjuntai dari langit-langit gua. Perhatikan koleksi di POI ini, lalu pilih: apa nama hiasan batu tersebut?','Ia tumbuh ke bawah dari langit-langit gua, bukan naik dari lantai.',NULL,NULL,ARRAY[]::text[],'Stalaktit terbentuk dari endapan mineral kalsit yang menumpuk perlahan dari tetesan air di langit-langit gua.',NULL
